/**
 * @name Path traversal vulnerability
 * @description User input used in file operations without proper path sanitization could lead to directory traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(FileSystemAccess fa |
      sink = fa.getAPathArgument()
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal vulnerability: user input flows to file path $@.", source.getNode(), "user input"

/**
 * @name File system access with user input
 * @description User input flowing into file system operations
 * @kind path-problem
 * @problem.severity error
 * @id py/file-system-access
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module FileAccessConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // File open operations
    exists(API::CallNode call |
      call = API::moduleImport("builtins").getMember("open").getACall() and
      sink = call.getArg(0)
    )
    or
    // os module file operations
    exists(API::CallNode call |
      call = API::moduleImport("os").getMember([
        "open", "remove", "unlink", "rename", "chmod", "chown",
        "stat", "lstat", "listdir", "mkdir", "makedirs", "rmdir"
      ]).getACall() and
      sink = call.getArg(0)
    )
    or
    // pathlib operations
    exists(API::CallNode call |
      call = API::moduleImport("pathlib").getMember("Path").getACall() and
      sink = call.getArg(0)
    )
    or
    // shutil operations
    exists(API::CallNode call |
      call = API::moduleImport("shutil").getMember([
        "copy", "copy2", "copytree", "move", "rmtree"
      ]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module FileAccessFlow = TaintTracking::Global<FileAccessConfig>;
import FileAccessFlow::PathGraph

from FileAccessFlow::PathNode source, FileAccessFlow::PathNode sink
where FileAccessFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "File system access with user input from $@.", source.getNode(), "user input"

/**
 * @name Regular expression injection (ReDoS)
 * @description User input flowing into regex compilation without proper escaping
 * @kind path-problem
 * @problem.severity warning
 * @id py/regex-injection
 * @tags security
 *        external/cwe/cwe-1333
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module RegexInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Check for regex compilation with user input
    exists(API::CallNode call |
      call = API::moduleImport("re").getMember(["compile", "match", "search", "findall", "finditer"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module RegexInjectionFlow = TaintTracking::Global<RegexInjectionConfig>;
import RegexInjectionFlow::PathGraph

from RegexInjectionFlow::PathNode source, RegexInjectionFlow::PathNode sink
where RegexInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Regular expression injection from $@.", source.getNode(), "user input"
